import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    words = data[1:1 + n]
    masks = {0}
    for w in words:
        m = 0
        ok = True
        for ch in w:
            b = 1 << (ord(ch) - 97)
            if m & b:
                ok = False
                break
            m |= b
        if not ok:
            continue
        masks.update([x | m for x in masks if not x & m])
    print(max(bin(x).count('1') for x in masks))


